from questions._util import q

QUESTIONS = [
    q("cicd-git", "easy", "A secret landed in a commit that is already on the remote. Why is deleting the file in a new commit not enough?", "The secret is still in the history anyone can clone.", "The remote keeps a cached copy for thirty days.", "Git only removes it once you run git gc locally.", "The deletion is not pushed until the branch merges.", "Rotate the secret first. History rewrite is a second, coordinated step, and clones made before it keep the secret anyway."),
    q("cicd-git", "medium", "main is protected and you need a reviewed change. What does the protection do?", "Blocks updates to main without the required review.", "Signs every commit that is merged into main.", "Prevents anyone from creating branches off main.", "Runs the CI workflows before every push to main.", "Protection is a policy on the remote, not a property of the commits. Required checks are configured with it but run on the pull request."),
    q("cicd-git", "medium", "You rebased a branch a colleague had already pulled. What did you change?", "The commit hashes, so their copy diverges.", "The commit authors, so blame is rewritten.", "Only the commit dates, not the hashes.", "Only the merge base, not the commits.", "Rebase rewrites commits, so every hash changes. Fine on a branch you own, hostile on a branch other people have based work on."),
    q("cicd-git", "hard", "Why release from a signed tag rather than a branch name?", "A tag names one commit. A branch moves.", "A tag carries the build artifacts with it.", "A branch cannot be checked out in CI.", "A tag is pushed with every git push.", "Release from a tag or a commit you recorded. Tags are not pushed by default, and a branch tip can still move."),
    q("cicd-actions", "medium", "A job must deploy to a cloud without a long-lived access key. What should it use?", "OIDC federation to a role scoped to the repo.", "An access key in an environment secret.", "A personal access token from a maintainer.", "The runner's instance role for all jobs.", "Federate the identity and constrain the subject to the repo and branch you trust. An instance role would be shared with every job on that runner."),
    q("cicd-actions", "hard", "pull_request_target runs with the base repository's secrets. Why is checking out the PR's code in it dangerous?", "The PR's code runs where secrets are visible.", "The PR's code can push directly to main.", "The workflow file is taken from the PR branch.", "The GITHUB_TOKEN is scoped to the fork.", "pull_request_target uses the base branch's workflow file, which is why it is trusted. Running the PR's scripts in it hands them the secrets. Use pull_request for untrusted code."),
    q("cicd-actions", "easy", "Where does a GitHub Actions workflow file live?", ".github/workflows", ".github/actions", ".ci/workflows", ".github/runners", "The file is code. Review it like the deploy it performs. .github/actions is a common place for local composite actions."),
    q("cicd-actions", "medium", "Why is actions/checkout@v4 weaker than a pin?", "The v4 tag can be moved to unreviewed code.", "The v4 tag skips the action's signature check.", "The v4 tag always resolves to a pre-release.", "The v4 tag runs with broader token permissions.", "A tag can move to a commit you have not read. A full SHA pin cannot. Pin third-party actions if the workflow can deploy or read secrets."),
    q("cicd-jenkins", "medium", "How do a Jenkins controller and its agents divide the work?", "The controller schedules. Agents run builds.", "Agents schedule. The controller runs builds.", "The controller runs builds. Agents store logs.", "Agents hold credentials. The controller runs.", "Keep the controller small and the agents replaceable. Running builds on the controller exposes its credentials and config."),
    q("cicd-jenkins", "easy", "Why is a Jenkinsfile in the repo better than a job built in the UI?", "It is reviewed and versioned with the code.", "It runs faster than a UI-defined job does.", "It gets access to more Jenkins plugins.", "It can run on agents, unlike UI jobs.", "If it is not in git, you cannot review the deploy."),
    q("cicd-jenkins", "medium", "How should credentials be used in a Jenkins job?", "From the credentials store, scoped and masked.", "From environment variables set on the agent.", "From a file committed beside the Jenkinsfile.", "From one global token shared by every folder.", "Scope and mask. A folder store is narrower than the global one, and agent env vars are visible to every job on that agent."),
    q("cicd-jenkins", "hard", "A shared agent just built an untrusted branch and will build main next. What is the risk?", "Leftover files or a poisoned cache can affect main.", "The untrusted build used up the agent's executors.", "The workspace for main is locked by the last build.", "The agent's JVM keeps the old branch's classpath.", "Agents do not wipe themselves unless you made them ephemeral. Use ephemeral agents, or isolate untrusted jobs from the agent that produces releases."),
    q("cicd-artifacts", "medium", "You rebuilt version 1.4.2 from a branch that moved and pushed over the old artifact. What broke?", "1.4.2 no longer names one set of bytes.", "1.4.2 now fails its checksum on every pull.", "1.4.2 lost its tag in the git repository.", "1.4.2 is now marked deprecated by the registry.", "Anyone who already verified 1.4.2 verified something else. Publish an immutable version. A new commit is a new version."),
    q("cicd-artifacts", "easy", "What is an artifact repository such as Nexus for?", "Storing the built outputs that deploys consume.", "Storing the source code that builds read from.", "Storing the pipeline's logs and test reports.", "Storing the cluster's manifests for GitOps.", "Source is git. The thing you run is the artifact."),
    q("cicd-artifacts", "medium", "What should move from staging to production during promotion?", "The same immutable artifact or digest.", "A fresh build from the same release tag.", "A fresh build from the same commit SHA.", "The same Dockerfile and build arguments.", "If you rebuild, you did not promote. Even the same commit can produce different bytes on a different day. You tested one thing and shipped another."),
    q("cicd-artifacts", "hard", "An image, a Helm chart and a git commit all claim to be the release. What has to agree?", "The chart pins the image digest, and git pins the chart version.", "The image tag and the chart version use the same number.", "The git tag name matches the image tag and the chart name.", "The chart's appVersion matches the git branch name.", "One release, one set of ids, written down. Matching names are a convention. Pinned digests and versions are the link."),
    q("cicd-promotion", "medium", "When is a manual approval gate before production useful?", "When a human accepts the artifact already built.", "When a human picks which commit gets built.", "When a human reruns the tests after approval.", "When a human rebuilds it on a trusted machine.", "Approve the thing you tested. Do not let the gate become a second, untested build."),
    q("cicd-promotion", "easy", "How should staging and production differ?", "Config and scale only.", "The commit deployed.", "The base image used.", "The build pipeline.", "If staging runs a different build, it did not rehearse the release."),
    q("cicd-promotion", "hard", "What should a rollback be?", "A deploy of a previous artifact you kept.", "A revert commit, built and deployed fast.", "A rebuild of the last release tag.", "A restore of the cluster from backup.", "A rollback that requires a rebuild is not a rollback. Keep the old artifact so you deploy known bytes during the incident."),
    q("cicd-promotion", "medium", "Where does environment-specific config belong?", "Outside the artifact, injected at deploy.", "In the image, set by a build arg per env.", "In the source, behind an environment flag.", "In the image, in one file per environment.", "One artifact, many configs. Build args per environment produce several 'same' versions. Secrets stay in the secret store."),
    q("cicd-runners", "medium", "What is a self-hosted runner on the production network, shared by every repository in the org?", "A pivot from any workflow into production.", "A safe default if forks cannot trigger it.", "Isolated per job, since each job has a workspace.", "Fine, as long as its disk is encrypted.", "Untrusted workflows become code running next to production, with caches and tokens left between jobs. Isolate runners and prefer ephemeral ones."),
    q("cicd-runners", "easy", "Why are GitHub-hosted runners a better default for a public repository?", "Untrusted jobs do not run on your network.", "They are the only runners forks can trigger.", "They cache dependencies between all jobs.", "They come with your cloud credentials set.", "Bring a self-hosted runner only when the job needs your private network, and then scope it."),
    q("cicd-runners", "hard", "A runner's cloud role can deploy, and the workflow checks out a pull request. What should be true of that role?", "Only protected branches' workflows can assume it.", "Any workflow in the repo can assume it, not forks.", "It can be assumed only from the runner's subnet.", "It can be assumed only while a PR is open.", "Fork PRs and unprotected branches must not get it. Same-repo branches can still run unreviewed code. The workflow's identity is part of the security boundary."),
    q("cicd-runners", "medium", "Why are caches on a shared runner a supply-chain issue?", "One job can poison what the next job trusts.", "Caches leak the runner's IP to package hosts.", "Caches skip the lockfile's integrity hashes.", "Caches make builds non-deterministic.", "Key the cache tightly or rebuild on a clean agent for the release job."),
    q("cicd-supply", "medium", "Why pin an action or a base image by digest?", "A moved tag cannot change what you run.", "A digest pulls faster than a tag does.", "A digest also verifies the publisher.", "A digest gets security fixes on its own.", "Update digests on purpose, with a diff, not because a tag moved overnight. A digest proves bytes, not who published them, and it never updates itself."),
    q("cicd-supply", "medium", "A dependency bot opened a PR that bumps a library. What do you still owe?", "A review and a passing test run.", "Nothing if the bump is a patch.", "A merge only if the CVE is critical.", "Nothing if the package is signed.", "The bot is a patch proposal. Your pipeline is the gate. Semver is a promise, not a proof."),
    q("cicd-supply", "hard", "A malicious version of a small library ran in your build, and the build had the deploy key. What failed?", "Build and deploy shared one credential.", "The lockfile allowed a range of versions.", "The registry did not scan the package.", "The build ran without network egress rules.", "Code you did not write had your production credentials. Split fetch, build, and deploy credentials. A build does not need to be able to ship."),
    q("cicd-supply", "easy", "What is an SBOM attached to a release?", "An inventory of what went into it.", "A list of its known vulnerabilities.", "A signature proving who built it.", "A record of who approved the release.", "It lets you answer 'are we affected' when a CVE appears. Generate it from the build you actually shipped. Scans and signatures are separate artifacts."),
    q("iac-workflow", "medium", "What is the usual Terraform change sequence?", "fmt, validate, plan -out, review, apply the plan.", "fmt, plan, apply, then validate the result.", "validate, apply -auto-approve, then plan.", "init, apply, then plan to confirm no drift.", "The plan is the review. Apply what you reviewed, not a new plan you have not read."),
    q("iac-workflow", "easy", "What do terraform fmt and validate catch?", "Style and internal consistency only.", "Drift between the code and the cloud.", "Permission errors in the cloud account.", "Resources that the change would replace.", "Validation is local. It does not prove the cloud will accept the change. The plan is what talks about real resources."),
    q("iac-workflow", "medium", "A module is called twice with different variables. What is that?", "Two instances of one pattern.", "A conflict on resource addresses.", "Two copies of one shared state.", "One instance with merged inputs.", "Addresses include the module instance name, so they do not collide. The duplication you want is in the module source, not in copy-paste."),
    q("iac-workflow", "hard", "Someone suggests terraform apply -target on the production stack for a one-off. What is the cost?", "Everything else is left unreconciled.", "State for untargeted resources is reset.", "The target's dependencies are skipped.", "The plan is saved without a state lock.", "Target includes dependencies but skips the rest of the desired state, so the next full apply can surprise you. Use it as a scalpel in an incident, then run a full plan."),
    q("iac-state", "medium", "What is Terraform state?", "A map from config addresses to real resource IDs.", "A backup of the cloud resources' configurations.", "A cache Terraform can rebuild from the cloud.", "A lock file that stops two applies at once.", "It is not a backup and cannot be fully rebuilt. Store it remotely, lock it, and restrict who can read it. It often contains secrets."),
    q("iac-state", "hard", "Two people apply at once against one state with no lock. What can happen?", "One overwrites the other's record of reality.", "The cloud rejects the second apply's calls.", "Terraform merges both writes like git does.", "The second apply waits for the first to end.", "Locking has to be configured on the backend. Without it, both think they own the next change."),
    q("iac-state", "medium", "A resource was created by hand. How does Terraform take it over without recreating it?", "Import it, then plan until the diff is empty.", "Add it to the config, then run apply.", "Run terraform refresh with it in the config.", "Add it to the config with lifecycle ignore.", "Import teaches state the existing ID. Applying the config alone would create a second one, and refresh only updates things already in state."),
    q("iac-state", "easy", "Why are separate states per environment a good default?", "A bad change in dev cannot hit production.", "Each state can use its own provider version.", "Separate states make plans run in parallel.", "Workspaces cannot share a state backend.", "Split by blast radius. A single global state is a single global mistake."),
    q("iac-modules", "medium", "What is a module output?", "A value the caller can use.", "A value the caller must set.", "A value shown only in plans.", "A value kept out of state.", "Outputs are the module's return values, such as an ID the rest of the stack needs. Inputs are the arguments, and outputs are stored in state."),
    q("iac-modules", "easy", "Why source a module from a git tag rather than a branch?", "A tag stays put. A branch moves.", "A tag downloads faster than a branch.", "A tag is required by terraform init.", "A tag includes the module's state.", "Pin the source. Review the bump."),
    q("iac-modules", "hard", "A module rename changed a resource address and Terraform plans to recreate a database. What avoids that?", "A moved block for the old and new address.", "A lifecycle prevent_destroy on the database.", "A terraform refresh before the next plan.", "A depends_on from the new module to the old.", "Addresses are identity to Terraform. Tell it the resource moved. prevent_destroy only makes the plan fail, and state mv is the older CLI form."),
    q("iac-modules", "medium", "A child module hard-codes a region. Why is that a problem for the caller?", "It cannot be reused elsewhere without a fork.", "The caller's provider region is overridden.", "Terraform rejects hard-coded values in modules.", "The module's resources cannot be imported.", "Regions, names, and sizes are inputs. Hard-coding is how a module becomes a one-off script."),
    q("iac-plan", "medium", "A plan shows destroy and create for a resource you only renamed in the console. What is Terraform saying?", "It will replace it, since the field forces a new one.", "It will rename it in place, with a short outage first.", "It will update the tags, then refresh the name.", "It will create a copy and keep the original.", "Read a replace. It is downtime and data loss if the resource is a database."),
    q("iac-plan", "easy", "Why does applying a saved plan from plan -out matter?", "You apply exactly the plan you reviewed.", "It skips the state lock during the apply.", "It applies faster by skipping a refresh.", "It lets you edit the plan before applying.", "Terraform refuses a saved plan if state changed since, so nothing slips in that you did not read. The file is not meant to be edited."),
    q("iac-plan", "hard", "The plan is empty and production is still wrong. What can explain it?", "Wrong state or workspace, or unmanaged resources.", "The provider cached the old values from last run.", "The plan used -refresh=false by default.", "The resource has a lifecycle create_before_destroy.", "Check the workspace, the backend, and whether the broken thing is even in this configuration. An empty plan only means config and state agree."),
    q("iac-plan", "medium", "A variable marked sensitive still appears in state. What did sensitive change?", "Whether the CLI shows it in output.", "Whether it is encrypted in state.", "Whether providers may log its value.", "Whether it is hashed before storage.", "Sensitive is a display control. The state and the cloud still have the value. Protect those."),
    q("iac-policy", "medium", "What are Checkov, tfsec or Conftest in a pipeline for?", "Failing a change that breaks a rule, before apply.", "Detecting drift between state and the cloud.", "Approving the plan in place of a reviewer.", "Fixing insecure settings in the Terraform code.", "Policy as code catches a public bucket or an open security group in the diff, while the author is still at the keyboard. It does not replace the plan review."),
    q("iac-policy", "easy", "A policy check flags a security group that allows 0.0.0.0/0 to SSH. What is it?", "A real finding, unless a narrow exception applies.", "A false positive, since NACLs filter SSH anyway.", "A warning to ignore if the instance has no IP.", "A finding to silence by disabling that check.", "Write the exception narrowly if it is real. Do not turn the check off globally."),
    q("iac-policy", "medium", "How does Sentinel or OPA attached to a Terraform run differ from a laptop linter?", "It is a gate the apply cannot skip.", "It checks the state file, not the plan.", "It runs against the live cloud account.", "It fixes the violations before apply.", "A laptop linter is advice. A gate is how the rule survives a hurry."),
    q("iac-policy", "hard", "Policy passed the plan and the cloud still ends up with a public bucket. How?", "Changed outside Terraform, or an attribute not covered.", "The policy ran against the previous plan file.", "The bucket's ACL is applied after the policy check.", "Policy checks only see resources, not data sources.", "Policy on the plan does not watch the console. Pair it with a cloud scan for drift."),
    q("iac-ansible", "medium", "How do Ansible and Terraform usually split the job?", "Terraform creates infra. Ansible configures it.", "Ansible creates infra. Terraform configures it.", "Terraform handles Linux. Ansible handles cloud.", "Ansible tracks state. Terraform is stateless.", "Use each for the loop it is good at. Driving both at the same resource without a boundary makes two sources of truth."),
    q("iac-ansible", "easy", "What happens when you run an idempotent Ansible task twice?", "The second run changes nothing.", "The second run reverts the first.", "The second run is skipped entirely.", "The second run fails as a duplicate.", "Idempotent means the second run is a no-op when the world already matches. It still runs and checks."),
    q("iac-ansible", "medium", "What is Ansible Vault for?", "Encrypting secrets in the automation repo.", "Fetching secrets from HashiCorp Vault.", "Storing the inventory of managed hosts.", "Signing playbooks before they are run.", "The encrypted file can live in git. The password cannot. Fetching from HashiCorp Vault is a lookup plugin."),
    q("iac-ansible", "hard", "A playbook writes a secret to a world-readable file in /tmp and deletes it at the end. What is still wrong?", "Others can read it until the delete runs.", "The delete task is skipped in check mode.", "/tmp is cleared only at the next reboot.", "The file is cached by Ansible's fact store.", "The secret is exposed on disk, and a failed play may never reach the delete. Use a secret store, a tight file mode, and no_log."),
    q("iac-secrets", "medium", "A cloud credential in terraform.tfvars was committed to git. What is it now?", "Leaked. Rotate it.", "Safe if the repo is private.", "Safe once you delete the file.", "Masked by Terraform in plans.", "tfvars is a common accident. Keep secrets in a secret manager or a CI secret and pass them in at run time."),
    q("iac-secrets", "easy", "What does SOPS let you do?", "Encrypt values in a file and still diff the keys.", "Store secrets in a server with an audit log.", "Scan git history for secrets before a push.", "Rotate cloud credentials on a schedule.", "The file can be reviewed. The value cannot be read without the key."),
    q("iac-secrets", "hard", "Why do External Secrets Operator and the CSI secrets driver exist?", "So the cluster fetches secrets from a manager.", "So secrets in git are encrypted at rest.", "So pods can share secrets across namespaces.", "So secrets are stored in etcd encrypted.", "The source of truth stays in the manager. The manifest only says which secret to fetch."),
    q("iac-secrets", "medium", "When are Sealed Secrets a reasonable choice?", "When git should hold ciphertext the cluster opens.", "When the plaintext must be visible for review.", "When secrets must be shared across clusters as-is.", "When you need to rotate secrets automatically.", "Review the fact that a secret changed. Do not review the secret. A sealed secret is bound to one cluster's key."),
    q("cloud-iam", "medium", "Why should a human and a workload not share an access key?", "Revocation breaks both, and audit cannot tell them apart.", "Cloud IAM limits each key to one source IP address.", "The workload's calls would count against the human's MFA.", "Keys used by two clients are disabled automatically.", "Give the human SSO and the workload a role it assumes. No long-lived shared key."),
    q("cloud-iam", "medium", "Why is an instance profile or workload identity better than a key on disk?", "Its credentials are short-lived and never stored.", "It gets broader permissions than a user key.", "Its calls are exempt from the audit trail.", "It works across every cloud account by default.", "There is no secret to commit, and the credential rotates. Scope the role to the API calls that instance actually makes."),
    q("cloud-iam", "easy", "What does least privilege mean for a deploy role?", "It can deploy and nothing more.", "It is admin, but only in CI runs.", "It is admin, with MFA required.", "It can deploy to every account.", "Start from the API calls the pipeline makes. Add those. Do not start from admin and hope."),
    q("cloud-iam", "hard", "A bucket policy and a role's identity policy both exist, across accounts. When is access allowed?", "Both allow it, and nothing denies it.", "Either allows it, unless SCPs deny it.", "The bucket policy allows it, whatever the role says.", "The role allows it, whatever the bucket says.", "Cross-account access needs both sides. An explicit deny anywhere wins. When access fails, read both documents and look for the deny."),
    q("cloud-vpc", "medium", "What makes a public subnet public?", "Its route table points 0.0.0.0/0 at an internet gateway.", "Its instances are given public IPs by default.", "Its network ACL allows inbound traffic from 0.0.0.0/0.", "Its CIDR comes from a public address range.", "The route is the definition. Instances still need a public address to be reachable, and many public subnets do not auto-assign one."),
    q("cloud-vpc", "easy", "What does VPC peering connect?", "Two private networks, by private IP.", "A VPC to the internet, through NAT.", "Two accounts' IAM, for shared roles.", "Two regions' DNS, for failover.", "Add routes both ways for the prefixes you need. Classic peering is not transitive."),
    q("cloud-vpc", "medium", "You put a database in a private subnet and a bastion in a public one. What did you gain?", "No public route to the database.", "No route from the app tier to it.", "No need for a security group on it.", "No way for it to make outbound calls.", "Administration goes through a host you can lock down. Private does not mean isolated from the VPC. Security groups still have to allow the app tier."),
    q("cloud-vpc", "hard", "Your only NAT gateway is in one availability zone, and that zone fails. What fails with it?", "Egress from private subnets routed to it.", "Inbound traffic to the load balancer.", "Traffic between instances in other zones.", "DNS resolution inside the whole VPC.", "A single NAT is a single egress path. Multi-AZ egress costs more and fails less."),
    q("cloud-sg", "medium", "A security group is stateful. You allow inbound 443. What do you not have to add?", "An outbound rule for that connection's replies.", "An inbound rule for health checks on 443.", "An outbound rule to the clients' subnets.", "A NACL rule for the inbound requests.", "Statefulness is the difference from a NACL, which needs the return path spelled out."),
    q("cloud-sg", "easy", "What does 0.0.0.0/0 on port 22 in a security group mean?", "Any IPv4 address may try SSH.", "Any address in the VPC may try SSH.", "Any address the NACL allows may try SSH.", "Any IPv4 or IPv6 address may try SSH.", "Use a VPN, a bastion, or SSM. Do not leave administration on the internet. IPv6 needs ::/0."),
    q("cloud-sg", "hard", "The security group allows the port and the connection times out. A NACL is on the subnet. What is a likely gap?", "The NACL drops the return traffic.", "The NACL overrides the group's allow.", "The group needs an outbound rule too.", "The group applies only after the NACL.", "The stateless NACL may allow the request and drop the ephemeral-port reply. Check both directions. A timeout is often a drop."),
    q("cloud-sg", "medium", "Why reference another security group as the source instead of a CIDR?", "It follows members as their IPs change.", "It also allows the return traffic both ways.", "It applies across regions and accounts.", "It is evaluated before any CIDR rules.", "Autoscaling changes IPs. Group membership is the stable name."),
    q("cloud-compute", "medium", "An autoscaling group replaces instances that fail health checks. What must be true for that to be safe?", "The instances hold no state you need.", "The instances use a launch template.", "The instances are in at least two AZs.", "The instances have detailed monitoring.", "Treat instances as cattle, with state elsewhere. A health check that matches the real failure is part of the design."),
    q("cloud-compute", "easy", "What is EC2 user data?", "A script or config run at first boot.", "An encrypted store for instance secrets.", "Per-user settings for SSH logins.", "Metadata about who launched the instance.", "It is readable from the metadata service and often logged. Do not put a long-lived password in it."),
    q("cloud-compute", "medium", "ECS, a VM and Kubernetes can all run a container. What is the platform choice really about?", "How much scheduling and rollout you run.", "Which one supports your container format.", "Which one can attach an IAM role to tasks.", "Which one can pull from a private registry.", "Pick the control plane your team can run at 2 a.m. All of them can run OCI images with cloud identities."),
    q("cloud-compute", "hard", "You baked a secret into an AMI. What is true after you rotate it in the secret manager?", "Every instance from that AMI has the old value.", "New instances fetch the new value at launch.", "The AMI is invalidated by the rotation event.", "Running instances update on their next reboot.", "Secrets in images outlive the rotation until you rebake and replace. Inject them at boot instead."),
    q("cloud-lb", "medium", "How do an application and a network load balancer differ?", "ALB routes HTTP by host and path. NLB forwards TCP/UDP.", "NLB routes HTTP by host and path. ALB forwards TCP/UDP.", "ALB has static IPs. NLB uses only DNS names.", "NLB terminates TLS. ALB cannot terminate it.", "Choose from the protocol you need to see. NLB is the one with static IPs, and both can terminate TLS."),
    q("cloud-lb", "easy", "What does a health check on /healthz do if the app does not serve that path?", "Marks every target unhealthy.", "Falls back to a TCP check.", "Uses / as the health path.", "Is ignored after a minute.", "The check has to match a path the app actually answers. A 404 is a failed check."),
    q("cloud-lb", "medium", "When do sticky sessions on a load balancer hurt?", "When one NAT hides a whole office.", "When targets use connection draining.", "When the balancer spans three AZs.", "When the cookie is set by the app.", "Source-IP affinity sends a NATed office to one target. Affinity is a workaround for state in the process. Moving the state out avoids it."),
    q("cloud-lb", "hard", "TLS terminates at the load balancer and the backend sees HTTP. What do you still verify?", "The backend cannot be reached around it.", "The backend has a copy of the certificate.", "The backend sends HSTS on every response.", "The backend validates the client's cert.", "A private path that bypasses the balancer bypasses the policy you thought you had."),
    q("cloud-registry", "medium", "Who controls push and pull on a cloud registry such as ECR?", "Cloud IAM, not the cluster's RBAC.", "The cluster's RBAC, not cloud IAM.", "The registry's own user accounts.", "The image signer's public key.", "The node role needs pull. The CI role needs push. Those are different principals."),
    q("cloud-registry", "easy", "What does scanning an image on push tell you?", "Known CVEs in its layers right now.", "Whether the image is safe to run.", "Whether the image was signed.", "Which CVEs are exploitable here.", "Scan is a signal, true at that moment. Admission or a rebuild is the control."),
    q("cloud-registry", "medium", "Production must pull only from your registry, not Docker Hub. What enforces it?", "Admission policy or egress rules.", "A pull-through cache in front of it.", "IAM policies on your own registry.", "A registry mirror in the daemon config.", "Block the other path. A mirror or cache is used when available, but a manifest naming docker.io can still pull directly."),
    q("cloud-registry", "hard", "How do immutable tags on the registry help?", "A tag cannot be pushed over with new bytes.", "A tag can no longer be deleted by anyone.", "A tag is converted into a digest on push.", "A tag must be signed before it is pulled.", "Combine it with a digest pin if the tag is a version you will trust."),
    q("cloud-object", "medium", "What does object storage for Terraform state need?", "Versioning, encryption, tight IAM, and locking.", "Public read for CI, with write limited by IAM.", "Lifecycle rules that expire old state versions.", "Replication to a second bucket in the region.", "State contains IDs and often secrets. Treat the bucket as production data and keep the old versions for recovery."),
    q("cloud-object", "easy", "How do a bucket and an object differ?", "The bucket is the policy boundary.", "The object sets the bucket's region.", "The bucket is one large stored file.", "The object holds the access policy.", "Block public access at the bucket. One object ACL should not be the only control."),
    q("cloud-object", "hard", "You enabled versioning after a ransomware-style overwrite. What does it give you?", "Prior versions of later overwrites only.", "Prior versions back to the bucket's creation.", "Protection from deletes by any user.", "Write-once storage for existing objects.", "The overwrite that already happened is not undone. Turn it on before the incident. Object Lock is the write-once feature."),
    q("cloud-object", "medium", "A lifecycle rule moves old build artifacts to cold storage. What must it not do to the current release?", "Expire it while you might roll back.", "Move it to a cheaper storage class.", "Change its key prefix in the bucket.", "Add a tag recording its age.", "Lifecycle is a cost tool. Exclude the versions your rollback story needs."),
    q("cloud-regions", "medium", "How do an availability zone and a region differ?", "A region is a group of isolated zones.", "A zone is a group of nearby regions.", "A region is one data center building.", "A zone is a region's backup location.", "A zone is a failure domain with its own power and network. One zone failing should not take down a regional service designed for it."),
    q("cloud-regions", "easy", "When does running a copy of a service in a second region help?", "When data and DNS can actually fail over.", "When the copy shares the first one's database.", "When the copy runs in the same city as users.", "When the copy is created after the outage.", "A region pair is a project: data, identity, and the switch. A second VPC with no data is a diagram."),
    q("cloud-regions", "hard", "A regional managed database fails over while the app is multi-AZ. What do the app instances see?", "A short break, then the same endpoint.", "No break, since the app is multi-AZ.", "A new endpoint name for the database.", "Each zone keeps its own primary.", "The DNS name moves to the new primary. Test reconnects. A failover your connection pool cannot survive is still an outage."),
    q("cloud-regions", "medium", "The only NAT, bastion, and CI runner are in one zone. What does that mean?", "That zone is your real availability.", "The region absorbs that zone failing.", "Zone failures only affect compute.", "The load balancer covers for them.", "Count the things that exist once. Those are the failure domains."),
    q("obs-logs", "medium", "Why put a request ID in every log line?", "To follow one request across services.", "To sort log lines in the right order.", "To deduplicate retries of the same line.", "To sample logs at a consistent rate.", "Generate it at the edge and pass it on. Searching by time across five services is how incidents get long."),
    q("obs-logs", "easy", "Why log to stdout in a container rather than to a file?", "The platform can collect it without exec.", "stdout is buffered, so logging is faster.", "Files cannot hold structured JSON logs.", "stdout is kept after the pod is deleted.", "Log to stdout unless you have a reason. A file in the container vanishes with it and needs something else to ship it."),
    q("obs-logs", "medium", "A log pipeline dropped messages during a deploy. What did you fail to budget?", "Shipper buffer, and a drop or block policy.", "Log retention days in the storage backend.", "Index fields in the log search cluster.", "Log level settings across all services.", "Logging has a failure mode. Decide it before the incident produces more logs than the pipeline can hold."),
    q("obs-logs", "hard", "You logged full HTTP headers and now a token is in the log store. What is true?", "It is exposed to every log reader. Rotate it.", "It is safe once retention deletes the logs.", "It is safe if the log store is encrypted.", "It is safe if you delete those log lines.", "Treat log access like secret access. Copies may already be in indexes and backups. Redact, and do not write secrets in the first place."),
    q("obs-metrics", "medium", "What does a Prometheus label with a user ID on every request do?", "Explodes cardinality and server memory.", "Slows scrapes, but only for that target.", "Gets dropped by Prometheus at ingestion.", "Turns the counter into a histogram.", "Each label value is a new series. Unbounded labels are an outage."),
    q("obs-metrics", "easy", "How do a counter and a gauge differ?", "A counter only rises. A gauge goes up and down.", "A counter goes up and down. A gauge only rises.", "A counter is per second. A gauge is a total.", "A counter is a float. A gauge is an integer.", "Counters reset only on restart, so use rate() on them. Use a counter for requests and a gauge for queue depth."),
    q("obs-metrics", "medium", "What does an average latency hide?", "The slow tail.", "The request rate.", "The error count.", "The median.", "A p99 and a count tell an incident story. An average can stay flat while a slice of users time out."),
    q("obs-metrics", "hard", "What do USE and RED stand for?", "Utilization, saturation, errors. Rate, errors, duration.", "Usage, saturation, errors. Requests, errors, delay.", "Utilization, speed, errors. Rate, errors, duration.", "Usage, scale, efficiency. Rate, errors, delay.", "USE is for resources, RED for services. A CPU and an HTTP API are not the same shape."),
    q("obs-traces", "medium", "What makes a trace more than a log?", "Spans linked across services by a trace ID.", "Timestamps with nanosecond precision.", "Structured fields instead of free text.", "A guaranteed record of every request.", "You want one trace when a request is slow and you do not know which hop. Traces are usually sampled."),
    q("obs-traces", "easy", "Why does trace sampling exist?", "Keeping every span costs too much.", "Unsampled traces lose their timing.", "Collectors reject full-rate traces.", "Sampling removes duplicate spans.", "Sample enough to debug. Do not assume you can keep everything."),
    q("obs-traces", "medium", "A service starts a span without the incoming request's parent ID. What is it?", "A broken trace that starts afresh at that hop.", "A sibling span under the same parent.", "A child span with an estimated parent ID.", "A dropped span the collector discards.", "Propagate the trace context. The header you forgot is why the picture stops at the proxy."),
    q("obs-traces", "hard", "You have traces and no metrics. What is painful?", "Alerting and capacity planning.", "Finding which hop was slow.", "Seeing a single request's path.", "Measuring one request's latency.", "Traces explain one request. Sampled, they are a poor counter of all requests. Keep a cheap metric for the alert and a trace for the example."),
    q("obs-prometheus", "medium", "Prometheus scrapes. What does the application do in the basic setup?", "Exposes an HTTP metrics endpoint.", "Pushes its metrics to Prometheus.", "Writes metrics to a log file.", "Sends metrics to Pushgateway.", "Prometheus pulls. If the target is down, the scrape fails and you see the gap. Pushgateway is for batch jobs."),
    q("obs-prometheus", "easy", "What is Grafana's role in front of Prometheus?", "Dashboards and queries over its data.", "Scraping targets for Prometheus.", "Long-term storage of the scraped samples.", "Routing and silencing the alerts.", "Do not expect Grafana to have samples Prometheus never scraped. Alertmanager routes alerts."),
    q("obs-prometheus", "medium", "What is Alertmanager's job?", "Routing, grouping and silencing alerts.", "Evaluating alert rules on a schedule.", "Storing alert history for dashboards.", "Scraping targets that raise alerts.", "The rule lives in Prometheus. A rule with no route is a rule nobody sees."),
    q("obs-prometheus", "hard", "When does a recording rule help?", "An expensive query runs on every dashboard.", "A target is too slow to scrape in time.", "A metric needs a label added at scrape time.", "An alert needs to wait before it fires.", "Record the aggregation you always ask for. Relabeling adds labels at scrape, and for: delays alerts."),
    q("obs-otel", "medium", "What does OpenTelemetry give an application?", "Vendor-neutral signals, exported anywhere.", "A storage backend for traces and metrics.", "A dashboard for traces, metrics and logs.", "An agent that profiles code automatically.", "Instrument once. Change the exporter when you change vendors."),
    q("obs-otel", "easy", "What does a collector in the path let you do?", "Batch, filter, and fan out telemetry.", "Store telemetry for months on disk.", "Generate traces without instrumentation.", "Query telemetry across all backends.", "The collector is a process you operate. It is also the place a bad config drops data."),
    q("obs-otel", "medium", "You send traces to a vendor and metrics to Prometheus. Why does OTel fit?", "One instrumentation, many exporters.", "It converts traces into metrics.", "It replaces Prometheus's scraping.", "It needs one backend for everything.", "The pipeline is allowed to fork. The app should not have to."),
    q("obs-otel", "hard", "A collector's queue fills and it is set to drop. What do you lose, and what should page?", "New telemetry. Page on the collector's drops.", "The app's requests. Page on app latency.", "Old telemetry. Page on storage capacity.", "Nothing. Page on the collector's CPU use.", "The app keeps running and the data vanishes. The pipeline's failure mode is a decision. Watch the pipeline, not only the app."),
    q("obs-alerts", "medium", "Why is an alert on CPU above 80% for a minute weak?", "CPU is a cause, not a user-facing symptom.", "One minute is too long to wait for CPU.", "CPU must be alerted on as a rate, not a gauge.", "80% is too low a threshold for any service.", "Users may be fine, and you will learn to ignore it. Alert on error rate, latency, or saturation that means the service is failing its job."),
    q("obs-alerts", "easy", "What does a good alert have?", "A clear cause and a next step.", "A threshold from industry norms.", "A page to everyone on the team.", "A graph of the last 24 hours.", "If it does not change what a human does, it is a chart, not an alert."),
    q("obs-alerts", "hard", "You silenced a noisy alert during an incident and forgot. What is the durable fix?", "Silences with expiry, and fixing the rule.", "Raise the threshold so it fires less often.", "Lower the alert to a warning in Slack.", "Delete the rule and rely on dashboards.", "Silence is a pause. An infinite silence is a deleted alert. The rule still needs to be true."),
    q("obs-alerts", "medium", "What happens when dev and production page on the same route?", "Production pages get ignored as noise.", "Dev alerts are dropped by deduplication.", "Pages are delayed by grouping intervals.", "Production alerts are silenced with dev.", "Separate the routes. The severity is part of the alert."),
]
